private _moveToSan(move: InternalMove, moves: InternalMove[]): string {
  let output = ''

  if (move.flags & BITS.KSIDE_CASTLE) {
    output = 'O-O'
  } else if (move.flags & BITS.QSIDE_CASTLE) {
    output = 'O-O-O'
  } else if (move.flags & BITS.NULL_MOVE) {
    return SAN_NULLMOVE
  } else {
    if (move.piece !== PAWN) {
      const disambiguator = getDisambiguator(move, moves)
      output += move.piece.toUpperCase() + disambiguator
    }

    if (move.flags & (BITS.CAPTURE | BITS.EP_CAPTURE)) {
      if (move.piece === PAWN) {
        output += algebraic(move.from)[0]
      }
      output += 'x'
    }

    output += algebraic(move.to)

    if (move.promotion) {
      output += '=' + move.promotion.toUpperCase()
    }
  }

  this._makeMove(move)
  if (this.isCheck()) {
    if (this.isCheckmate()) {
      output += '#'
    } else {
      output += '+'
    }
  }
  this._undoMove()

  return output
}

// convert a move from Standard Algebraic Notation (SAN) to 0x88 coordinates
private _moveFromSan(move: string, strict = false): InternalMove | null {
  // strip off any move decorations: e.g Nf3+?! becomes Nf3
  let cleanMove = strippedSan(move)

  if (!strict) {
    if (cleanMove === '0-0') {
      cleanMove = 'O-O'
    } else if (cleanMove === '0-0-0') {
      cleanMove = 'O-O-O'
    }
  }

  //first implementation of null with a dummy move (black king moves from a8 to a8), maybe this can be implemented better
  if (cleanMove == SAN_NULLMOVE) {
    const res: InternalMove = {
      color: this._turn,
      from: 0,
      to: 0,
      piece: 'k',
      flags: BITS.NULL_MOVE,
    }
    return res
  }

  let pieceType = inferPieceType(cleanMove)
  let moves = this._moves({ legal: true, piece: pieceType })

